          response.end("ERR:\n" + error.message);
        } else {
          if (stdout) {
            response.end('' + iconv.decode(stdout, "gbk"));
          } else if (stderr) {
            response.end("ERR:\n" + iconv.decode(stderr, "gbk"));
          }
        }
      });
    } catch (error) {
      response.end("ERR:\n" + error);
    }
  }
}).listen(3004);

